  // Panel (gradient background with border)
  // -----------------------------------------------------------------
  const panelWidth = 3.4;
  const panelHeight = 1.9;
  const panelGeom = new PlaneGeometry(panelWidth, panelHeight);
  const panelMat = new MeshStandardNodeMaterial();

  const uvNode = uv();
  const topColor = color('#1a1a22');
  const bottomColor = color('#111116');
  panelMat.colorNode = mix(topColor, bottomColor, uvNode.y);

  panelMat.metalness = 0.2;
  panelMat.roughness = 0.6;
  panelMat.clearcoat = 0.1;

  // Simple hairline border via emissive (approximation)
  panelMat.emissiveNode = color('#26262f');
  panelMat.emissiveIntensity = 1.0;
  panelMat.transparent = true;

  const panelMesh = new Mesh(panelGeom, panelMat);
  root.add(panelMesh);

  // -----------------------------------------------------------------
  // Oversized quotation mark (SDF plane, slight extrusion via Z scale)
  // -----------------------------------------------------------------
  const quoteMark = ctx.fontAtlas.createText({
    text: '"',
    fontFamily: 'Lora',
    fontSize: 62,
    fontWeight: 600,
    color: '#ff2a38',
  });

  // Desired visual height: 0.62 scene units
  const markHeight = 0.62;
  const markScale = markHeight / quoteMark.userData.originalHeight; // assume atlas provides originalHeight
  quoteMark.scale.set(markScale, markScale, 0.04);
  const pad = 0.5; // 2 × base unit (0.25 * 2)
  const markX = -panelWidth / 2 + pad + markHeight / 2;
  const markY = panelHeight / 2 - pad - markHeight / 2;
  quoteMark.position.set(markX, markY, 0.001);
  root.add(quoteMark);

  // -----------------------------------------------------------------
  // Quote text (multi‑line)
  // -----------------------------------------------------------------
  const quoteLines = [
    'The bezel action alone is worth the wait.',
    'Nothing else on my wrist feels this considered.',
  ];
