    text: quoteLines.join('\n'),
    fontFamily: 'Lora',
    fontSize: 20,
    fontWeight: 400,
    lineHeight: 1.45,
    color: '#e8ecf2',
    maxWidth: 2.4,
    align: 'left',
  });
  const quoteY = markY - markHeight / 2 - 0.25;
  quoteMesh.position.set(-panelWidth / 2 + pad, quoteY, 0.03);
  root.add(quoteMesh);

  // -----------------------------------------------------------------
  // Attribution line + accent rule
  // -----------------------------------------------------------------
  const attribution = ctx.fontAtlas.createText({
    text: 'M. OKAFOR',
    fontFamily: 'JetBrains Mono',
    fontSize: 13,
    fontWeight: 700,
    letterSpacing: 0.08,
    lineHeight: 1.2,
    color: '#e8ecf2',
  });
  const attribY = quoteY - 0.25;
  attribution.position.set(-panelWidth / 2 + pad, attribY, 0.03);
  root.add(attribution);

  const ruleGeom = new PlaneGeometry(0.2, 0.02);
  const ruleMat = new MeshStandardNodeMaterial({ color: '#ff2a38', emissive: '#ff2a38', emissiveIntensity: 1.4 });
  const ruleMesh = new Mesh(ruleGeom, ruleMat);
  ruleMesh.position.set(-panelWidth / 2 + pad + 0.2 / 2, attribY, 0.03);
  root.add(ruleMesh);

  // -----------------------------------------------------------------
  // Caption
  // -----------------------------------------------------------------
  const caption = ctx.fontAtlas.createText({
    text: 'COLLECTOR SINCE 2019',
    fontFamily: 'JetBrains Mono',
    fontSize: 9,
    fontWeight: 400,
    letterSpacing: 0.12,
    lineHeight: 1.4,
    color: '#e8ecf2',
  });
  caption.position.set(-panelWidth / 2 + pad, attribY - 0.2, 0.03);
  root.add(caption);

  // -----------------------------------------------------------------
  // Animations (GSAP)
  // -----------------------------------------------------------------
  const timelines = [];

  // Panel fade‑up
  const panelFade = gsap.fromTo(
    panelMat,
    { opacity: 0, transparent: true, position: { y: panelMesh.position.y + 0.2 } },
    { opacity: 1, duration: 0.5, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' }
  );
  timelines.push(panelFade);

